using System;using System.IO;using System.Collections;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using NarutoVR.QingGuiR03Review;using Object=UnityEngine.Object;
[InitializeOnLoad] public static class QingGuiR03OpticsOnly {
 const string Key="QingGuiR03OpticsOnly.Run";const string Out=QingGuiR03FirstLook.Logs+"/optics-only-01";static IEnumerator routine;static int frame;
 static QingGuiR03OpticsOnly()=>EditorApplication.update+=Boot;
 public static void Run(){Directory.CreateDirectory(Out);EditorSceneManager.OpenScene(QingGuiR03FirstLook.Root+"/QingGuiR03_FirstLook.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void Boot(){if(!Application.isPlaying||EditorApplication.isCompiling||!SessionState.GetBool(Key,false))return;SessionState.SetBool(Key,false);new GameObject("R03 independent optics tick").AddComponent<QingGuiR03ReviewTick>();QingGuiR03ReviewTick.Tick=Step;routine=Check();}
 static IEnumerator Check(){var c=Camera.main;c.enabled=true;QualitySettings.realtimeReflectionProbes=true;var p=Object.FindFirstObjectByType<ReflectionProbe>();int id=p.RenderProbe();for(int i=0;i<100&&!p.IsFinishedRendering(id);i++)yield return null;c.enabled=false;var item=GameObject.Find("R03 Actual three-part object");var optics=QingGuiR03FirstLook.VerifyOpticsOnly(c,item,RenderSettings.sun,p,Out);while(optics.MoveNext())yield return optics.Current;File.WriteAllText(Out+"/result.txt","PASS independent optical negatives; geometric quick-fit intentionally separate.\n");try{var console=QingGuiR03QuickFit.Check(item,Out);Object.Destroy(console);}catch(Exception e){File.WriteAllText(Out+"/separate-quickfit-failure.txt",e.ToString());}EditorApplication.Exit(0);}
 static void Step(){try{if(++frame>220)throw new Exception("Optics frame bound");if(!routine.MoveNext())EditorApplication.Exit(0);}catch(Exception e){QingGuiR03ReviewTick.Tick=null;File.WriteAllText(Out+"/failure.txt",e.ToString());EditorApplication.Exit(3);}}
}
